import 'dart:io';import 'package:path/path.dart' as p;import '../../addons/application/addon_install_controller.dart';import '../../addons/domain/installed_addon.dart';import '../plugin_uri.dart';import 'embedded_python_executor.dart';import 'legacy_plugin_invocation.dart';import 'legacy_plugin_result.dart';import 'legacy_runtime_request.dart';import 'process_python_executor.dart';import 'python_runtime_bundle.dart';
class LegacyPluginRuntime{LegacyPluginRuntime({required this.addonInstallController,this.requestHandler,PythonRuntimeBundle? runtimeBundle,PythonExecutableResolver? pythonResolver}):_runtimeBundle=runtimeBundle??PythonRuntimeBundle(),_pythonResolver=pythonResolver??const PythonExecutableResolver();final AddonInstallController addonInstallController;final LegacyRuntimeRequestHandler? requestHandler;final PythonRuntimeBundle _runtimeBundle;final PythonExecutableResolver _pythonResolver;int _nextHandle=1;Future<LegacyPluginResult>invokeRoot(String id)=>invokeUrl('plugin://$id/');Future<LegacyPluginResult>invokeUrl(String raw)async{await addonInstallController.initialize();late PluginUri u;try{u=PluginUri.parse(raw);}on FormatException catch(e){return _failure(e.message.toString());}final a=addonInstallController.installedById(u.addonId);if(a==null)return _failure('Addon ${u.addonId} não está instalado.');final entry=a.manifest.pythonEntrypoint;if(entry==null||entry.trim().isEmpty)return _failure('${a.manifest.name} não declara xbmc.python.pluginsource.');return _invokeAddon(addon:a,entrypoint:entry,invocationUrl:raw,query:_queryFor(raw));}
Future<LegacyPluginResult>invokeScriptAddon(String id,{List<String> arguments=const []})async{await addonInstallController.initialize();final a=addonInstallController.installedById(id);if(a==null)return _failure('Addon $id não está instalado.');final entry=a.manifest.pythonScriptEntrypoint;if(entry==null||entry.trim().isEmpty)return _failure('${a.manifest.name} não declara xbmc.python.script.');final ep=p.normalize(p.join(a.installPath,entry));return _invokeAddon(addon:a,entrypoint:entry,invocationUrl:'script://$id',query:'',argv:[ep,...arguments]);}
Future<LegacyPluginResult>_invokeAddon({required InstalledAddon addon,required String entrypoint,required String invocationUrl,required String query,List<String>? argv})async{final runtime=await _runtimeBundle.materialize();final dirs=await addonInstallController.directories();final support=p.dirname(dirs.addonsRootPath),profile=p.join(dirs.addonDataRootPath,addon.manifest.id);await Directory(profile).create(recursive:true);final temp=p.join(Directory.systemTemp.path,'addko');await Directory(temp).create(recursive:true);final inv=LegacyPluginInvocation(addonId:addon.manifest.id,addonPath:addon.installPath,entrypointPath:p.normalize(p.join(addon.installPath,entrypoint)),pluginUrl:invocationUrl,handle:_nextHandle++,query:query,profilePath:profile,addonsRoot:dirs.addonsRootPath,addonDataRoot:dirs.addonDataRootPath,shimsPath:runtime.shimsPath,pythonPaths:_pythonPathsFor(addon),specialPaths:{'special://home':support,'special://profile':support,'special://userdata':support,'special://temp':temp},argv:argv);if(Platform.isAndroid)return EmbeddedPythonExecutor(workerScriptPath:runtime.workerPath,requestHandler:requestHandler).invoke(inv);final python=await _pythonResolver.resolve();if(python==null)return _failure('Nenhum runtime Python foi encontrado. No desktop, configure Python 3 ou ADDKO_PYTHON; no Android o AddKo usa o runtime CPython embarcado.');return ProcessPythonExecutor(pythonExecutable:python,workerScriptPath:runtime.workerPath,requestHandler:requestHandler).invoke(inv);}
List<String>_pythonPathsFor(InstalledAddon addon){final r=<String>[],visited=<String>{};void collect(InstalledAddon current){if(!visited.add(current.manifest.id))return;for(final d in current.manifest.dependencies){if(d.optional||d.id.startsWith('xbmc.')||d.id.startsWith('kodi.'))continue;final i=addonInstallController.installedById(d.id);if(i==null)continue;collect(i);var added=false;for(final e in i.manifest.extensions){if(e.point!='xbmc.python.module')continue;final lib=e.library?.trim();if(lib!=null&&lib.isNotEmpty){r.add(p.normalize(p.join(i.installPath,lib)));added=true;}}if(!added)r.add(i.installPath);}}collect(addon);return r.toSet().toList(growable:false);}String _queryFor(String raw){final u=Uri.parse(raw);return u.hasQuery?'?${u.query}':'';}LegacyPluginResult _failure(String m)=>LegacyPluginResult(items:const [],logs:const [],succeeded:false,errorMessage:m);}
